#include <vector>
#include <algorithm>
#include <numeric>

class Solution {
public:
    long long largestEvenSum(std::vector<int>& nums, int k) {
        std::sort(nums.rbegin(), nums.rend());
        long long currSum = 0;
        int minOddChosen = -1, minEvenChosen = -1;

        for (int i = 0; i < k; ++i) {
            currSum += nums[i];
            if (nums[i] % 2 == 1) {
                if (minOddChosen == -1 || nums[i] < minOddChosen) minOddChosen = nums[i];
            } else {
                if (minEvenChosen == -1 || nums[i] < minEvenChosen) minEvenChosen = nums[i];
            }
        }

        if (currSum % 2 == 0) return currSum;

        int maxOddRest = -1, maxEvenRest = -1;
        for (int i = k; i < (int)nums.size(); ++i) {
            if (nums[i] % 2 == 1) {
                if (maxOddRest == -1 || nums[i] > maxOddRest) maxOddRest = nums[i];
            } else {
                if (maxEvenRest == -1 || nums[i] > maxEvenRest) maxEvenRest = nums[i];
            }
        }

        long long ans = -1;
        if (minOddChosen != -1 && maxEvenRest != -1) {
            ans = std::max(ans, currSum - minOddChosen + maxEvenRest);
        }
        if (minEvenChosen != -1 && maxOddRest != -1) {
            ans = std::max(ans, currSum - minEvenChosen + maxOddRest);
        }
        return ans;
    }
};

import java.util.Arrays;

class Solution {
    public long largestEvenSum(int[] nums, int k) {
        Arrays.sort(nums);
        int n = nums.length;
        long currSum = 0;
        int minOddChosen = -1, minEvenChosen = -1;

        for (int i = 0; i < k; i++) {
            int val = nums[n - 1 - i];
            currSum += val;
            if (val % 2 == 1) {
                if (minOddChosen == -1 || val < minOddChosen) minOddChosen = val;
            } else {
                if (minEvenChosen == -1 || val < minEvenChosen) minEvenChosen = val;
            }
        }

        if (currSum % 2 == 0) return currSum;

        int maxOddRest = -1, maxEvenRest = -1;
        for (int i = k; i < n; i++) {
            int val = nums[n - 1 - i];
            if (val % 2 == 1) {
                if (maxOddRest == -1 || val > maxOddRest) maxOddRest = val;
            } else {
                if (maxEvenRest == -1 || val > maxEvenRest) maxEvenRest = val;
            }
        }

        long ans = -1;
        if (minOddChosen != -1 && maxEvenRest != -1) {
            ans = Math.max(ans, currSum - minOddChosen + maxEvenRest);
        }
        if (minEvenChosen != -1 && maxOddRest != -1) {
            ans = Math.max(ans, currSum - minEvenChosen + maxOddRest);
        }
        return ans;
    }
}

